import pathlib,subprocess,datetime,json,hashlib,os,shutil
R=pathlib.Path(__file__).resolve().parents[3];F=R/'framework/diagrams/f18';cli=os.environ.get('D2_CLI','d2');checks=[]
for slug in ['factors','corpus']:
 source=f'framework/diagrams/f18/{slug}.d2'
 commands=[[cli,'fmt','--check',source],[cli,'validate',source]]
 for theme,id in [('light','4'),('dark','201')]:commands.append([cli,'--layout=dagre','--theme='+id,'--pad=24','--timeout=30',source,f'framework/diagrams/f18/{slug}-{theme}.svg'])
 for command in commands:
  p=subprocess.run(command,cwd=R,text=True,capture_output=True);checks.append({'command':' '.join(['d2']+command[1:]),'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr});assert p.returncode==0,p.stderr
r={'recorded_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'generator':subprocess.check_output([cli,'--version'],text=True).strip(),'layout':'dagre','themes':{'light':4,'dark':201},'pad':24,'checks':checks,'sha256':{str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in F.iterdir() if p.suffix in ['.svg','.d2']},'cli_sha256':hashlib.sha256(pathlib.Path(shutil.which(cli) or cli).read_bytes()).hexdigest(),'artifact_edits':'sources only; all SVG regenerated by D2; no manual SVG edits','scope':'F18 conceptual summaries with measured single-shard sample; no internal call/segment/merge diagram'}
(F/'generation.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n');print('Two D2 sources, four SVG exports passed')
